#define _CRT_SECURE_NO_WARNINGS
#include <stdio.h>

int main(void) {
    FILE *f = fopen("best.txt", "w");
    if (f == NULL) {
        fprintf(stderr, "Could not save\n");
        return 1;
    }
    fprintf(f, "%d\n", 120);
    fclose(f);

    int best = 0;
    f = fopen("best.txt", "r");
    if (f != NULL) {
        fscanf(f, "%d", &best);
        fclose(f);
    }
    printf("Best: %d\n", best);
    return 0;
}
